  "site.about.clubsEyebrow": "Le réseau",
  "site.about.clubsText": "Chaque club a sa maison et sa communauté, avec la même direction technique.",
  "site.about.clubsTitle": "Nos clubs",
  "site.about.heroText": "Judo Arte e Vida est né en Algarve autour d'un entraîneur et d'une idée : le judo est bien plus qu'un sport.",
  "site.about.heroTitle": "Une famille autour du tatami",
  "site.about.story1": "Tout commence avec Matias Luwawa, judoka depuis 1994. Entraîneur depuis 2006 et arbitre depuis 2009, il est devenu arbitre d'élite et a bâti, dojo après dojo, un réseau de clubs en Algarve : Lagos, Albufeira, Alvor.",
  "site.about.story2": "Aujourd'hui, Judo Arte e Vida réunit des clubs, des entraîneurs, des athlètes et des familles qui partagent les mêmes valeurs, ainsi qu'une plateforme qui les relie : inscriptions, cotisations, présences, compétitions et ranking au même endroit.",
  "site.about.storyEyebrow": "Notre histoire",
  "site.about.storyTitle": "Du premier tatami à un réseau de clubs",
  "site.about.team.ariel.name": "Ariel",
