  "site.values.art.text": "La technique comme forme d'art : chaque projection est précision, respect et élégance.",
  "site.values.art.title": "Art",
  "site.values.discipline.text": "Le salut, la constance, le respect du partenaire : le judo apprend à tomber et à se relever.",
  "site.values.discipline.title": "Discipline",
  "site.values.eyebrow": "Nos valeurs",
  "site.values.life.text": "Familles, amitiés, communauté : ce que l'on apprend sur le tatami reste pour la vie.",
  "site.values.life.title": "Vie",
  "site.values.text": "Trois mots dans le nom, une façon d'être sur le tatami.",
  "site.values.title": "Art, discipline, vie",
  "site.vision.goalText": "C'est notre objectif : un réseau qui grandit en gardant la même âme.",
  "site.vision.goalTitle": "Plus de clubs, plus d'enfants sur le tatami, plus de familles impliquées",
  "site.vision.heroText": "Nous voulons que chaque enfant, chaque famille et chaque athlète trouve dans le judo discipline, respect et joie : dans n'importe quel club du réseau.",
  "site.vision.heroTitle": "Le judo comme école de vie, à la portée de tous",
  "site.vision.mission1": "Le judo a un code moral : respect, sincérité, courage, maîtrise de soi. Nous le portons du tatami à la maison, à l'école et dans la vie.",
  "site.vision.mission2": "Et nous voulons que les clubs puissent s'y consacrer, pas à la paperasse : c'est pourquoi le réseau dispose d'une plateforme qui gère toute seule cotisations, présences, compétitions et comptes.",
  "site.vision.missionEyebrow": "Notre mission",
  "site.vision.missionTitle": "Former des personnes, pas seulement des judokas",
  "site.vision.pillar.community.text": "Clubs, mairies, associations et sponsors qui grandissent ensemble en Algarve.",
  "site.vision.pillar.community.title": "Communauté",
  "site.vision.pillar.excellence.text": "Des premiers pas au podium : championnats régionaux, nationaux et vétérans.",
  "site.vision.pillar.excellence.title": "Excellence sportive",
  "site.vision.pillar.family.text": "Parents et enfants sur le même tatami, des familles impliquées à chaque étape.",
  "site.vision.pillar.family.title": "Famille",
  "site.vision.pillar.inclusion.text": "Judo adapté pour les personnes autistes et pour les personnes aveugles et malvoyantes : le tatami appartient à tous.",
  "site.vision.pillar.inclusion.title": "Inclusion",
  "site.vision.pillar.innovation.text": "La technologie au service du judo : moins de papier, plus de temps sur le tatami.",
  "site.vision.pillar.innovation.title": "Innovation",
  "site.vision.pillar.values.text": "Le salut, le respect du partenaire, la discipline : l'art avant la victoire.",
